import java.util.*;
import java.util.stream.*;
class Main {
  public static void main(String[] args) {
    List<Integer> xs = new ArrayList<>(List.of(1, 2, 3, 4, 5));
    List<Integer> out = xs.stream()
        .filter(x -> x % 2 == 0)
        .map(x -> x * 2)
        .collect(Collectors.toList());
    System.out.println(out);
  }
}

